const A = Object.assign({ key: (args || {}).key }, LANES[(args || {}).key] || {})
const MAIN = '/Users/boriskarpman/projects/RealTimeAudio'
const RPT = '.harmony/.reports/s-rta-1004'
const PIN = '185147b'
const BF2 = MAIN + '/.claude/worktrees/bf2'
const KEYS = MAIN + '/.claude/worktrees/bf2keys'
const KEY = A.key
const PLAN_FILE = RPT + '/plan-' + KEY + '.md'
const RULING_FILE = RPT + '/ruling-' + KEY + '.md'
const PAPERS_FILE = RPT + '/attack-' + KEY + '-papers.md'
const SHEETS = (A.sheets || []).map(s => MAIN + '/' + RPT + '/facts-' + s + '.md')

const READS = `HOW TO READ (binding): you are read-only. main = ${MAIN}, pinned at commit ${PIN}: first run git -C ${MAIN} rev-parse --short HEAD (must print ${PIN}) and git -C ${MAIN} status --short -- src tests docs CMakeLists.txt (must print nothing); then read plain files under ${MAIN}/src, ${MAIN}/tests, ${MAIN}/docs/claude, ${MAIN}/CLAUDE.md (if either check fails, read only through git -C ${MAIN} show ${PIN}:<path> and say so). The STOPPED sync-dial branches are a source of parts only, each in a clean worktree nobody edits: lane/bf2 at 740b6d6 in ${BF2}, lane/bf2-keys at 9eab9bd in ${KEYS} (check git -C <worktree> rev-parse --short HEAD and status --short before reading plain files there). Reports and Boris's records under ${MAIN}/.harmony/ are plain files. Never build, never run a test, never launch the app or a probe, never touch a running Audio-DNA or Resolume Arena (they are Boris's). Never cd in a command; absolute paths only. If a user message was relayed to you, Harmony has already filed and answered it; it never replaces this task.`

const INPUTS = `INPUTS (big files are indexed -- grep -n '^#' first, then read ranges):
- BORIS'S WORDS, binding, read first: ${MAIN}/.harmony/binding-decisions.md, every section headed "2026-10-04 (s-rta-1004)" (his words in quotes; the text after "->" is Harmony's consequence text, not his). The whole messages with the questions as asked: ${MAIN}/.harmony/boris-feedback-backlog.md, the sections stamped 2026-10-04 (BF38..BF60). Quote him ONLY verbatim and only from these two files.
- THE QUESTIONS AS ASKED, Harmony's readings R1..R32 told to him, and what is still OPEN: ${MAIN}/${RPT}/boris-clarify-26-37.md, -38-41.md, -42-44.md, -45-46.md, -47-49.md, -50.md. OPEN at this moment: 47 (the set of bar counts), 48 (which Record boxes), 49 (what the nudge number reads after a Resync; default 0), 50 (key and MIDI settings between launches; default: the app remembers them). Where your lane touches an open one, design so that either answer is a small change and say which line changes.
- THE FACT SHEETS (verified today; each ends with a "VERIFICATION" section -- its corrections OVERRIDE the sheet's own body): ${SHEETS.join(', ')}. Others exist in the same folder (ls ${MAIN}/${RPT}/facts-*.md). Resolume screenshots Boris sent: ${MAIN}/${RPT}/boris-resolume/*.png (Read the ones your lane concerns).
- HARMONY'S RULINGS on the stopped sync dial: ${MAIN}/.harmony/.reports/s-rta-1003b/rulings-bf2.md (H-17: the lane is superseded; what is void, what is kept as parts).
- PROJECT RULES: ${MAIN}/CLAUDE.md (sacred rules, UI patterns, the pitfall index), ${MAIN}/docs/claude/pitfalls.md (read the numbered entries your lane touches), the topic docs under ${MAIN}/docs/claude/, ${MAIN}/.harmony/RIG-RULES.md (how live gates run on a machine Boris is using) and the SCREEN-SAFETY LAW in ${MAIN}/.harmony/HANDOFF.md (no gate ever opens an Output window; no full-screen capture; no synthetic input).
- THE FORM a ruling takes in this project (mirror its section list, not its content): ${MAIN}/.harmony/.reports/s-rta-1003b/ruling-bf2-stops.md.${A.extraInputs ? '\n' + A.extraInputs : ''}`

const RULES = `RULES OF THE DOCUMENT: Boris is quoted ONLY verbatim; anything Harmony requires is written as "Harmony constraint:". No code blocks longer than a signature. The real-time rules hold (no allocation / lock / syscall on the audio callback; analysis steady state allocation-free; the render thread never waits; no new mutex without saying so). A pre-registered bar is never loosened: it is met, or reported. Every new test or gate row is RED first and has a named RED arm (a mutant or the tree before the change). Prefer the smallest change that is correct; say what is NOT in this lane. No on-screen text that announces an event or a failure (Boris 2026-10-03 and 2026-10-04: only an unsaved clip recording, an unsaved show recording, a failed Save of a show or deck, not enough disk space to record, and the quit window); a STATE display is allowed. Every slider is a ResettableSlider with a default; popup menus use showMenuAsync with the top-level parent. Anything Boris will SEE goes through the visual gate (a capture builder, then five critic seats) before he sees it: name the states to capture. Questions for Boris are numbered ${A.qFirst}..${A.qLast} (new numbers; a question already shown to him is never re-worded), each in plain words with a default A, and only what is genuinely his (taste, behaviour he performs with); a technical fork is ruled here, not asked.
${A.constraints || ''}`

const PS = { type: 'object', properties: { plan_path: { type: 'string' }, status: { type: 'string', enum: ['DONE', 'PARTIAL'] }, summary: { type: 'string' }, forks: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, choice: { type: 'string' }, runner_up: { type: 'string' } }, required: ['id', 'choice'] } }, not_verified: { type: 'array', items: { type: 'string' } } }, required: ['plan_path', 'status', 'summary', 'forks'] }
const AS = { type: 'object', properties: { seat: { type: 'string' }, attacks: { type: 'array', items: { type: 'object', properties: { id: { type: 'string' }, target: { type: 'string' }, claim: { type: 'string' }, evidence: { type: 'string' }, severity: { type: 'string', enum: ['MUST', 'SHOULD', 'NIT'] }, proposed_change: { type: 'string' } }, required: ['id', 'target', 'claim', 'evidence', 'severity'] } }, strongest_point: { type: 'string' }, citations_rechecked: { type: 'boolean' } }, required: ['seat', 'attacks', 'strongest_point', 'citations_rechecked'] }
const RS = { type: 'object', properties: { ruling_path: { type: 'string' }, papers_path: { type: 'string' }, status: { type: 'string', enum: ['DONE', 'PARTIAL'] }, verdict: { type: 'string' }, amendments: { type: 'number' }, attacks_ruled: { type: 'number' }, stages: { type: 'array', items: { type: 'object', properties: { key: { type: 'string' }, scope: { type: 'string' } }, required: ['key', 'scope'] } }, boris_questions: { type: 'array', items: { type: 'string' } }, harmony_decisions: { type: 'array', items: { type: 'string' } }, facts_harmony_must_measure: { type: 'array', items: { type: 'string' } }, strongest_counterargument: { type: 'string' } }, required: ['ruling_path', 'status', 'verdict', 'amendments', 'attacks_ruled', 'stages'] }

phase('Plan')
const plan = await agent(`PLAN AUTHORING (architect) -- Audio-DNA (C++20 / JUCE / OpenGL live audio-reactive VJ app, macOS), lane "${KEY}": ${A.title}. You author the position; a blind council attacks it; an architect ruling follows; Harmony decides.
GOAL: ${A.goal}
${READS}
${INPUTS}
ITEMS. For each: what is VERIFIED (a file:line at ${PIN}, or a row of a fact sheet whose VERIFICATION section did not overturn it), the forks, the choice, why the runner-up loses, the change by file / function (no code), the RED-first tests and their mutants, the gate row.
${A.items}
OUTPUT: write the plan to REPORT_FILE (literal path below, relative to ${MAIN}; bash heredoc to exactly that path). Sections: 1 GOAL; 2 ESTABLISHED FACTS (ONLY verified lines, each with file:line or the sheet and row; anything else is labelled INFERRED or ASSUMED where it is used); 3 ITEMS; 4 STAGES + ORDER (one builder context per stage; what each proves; which files each owns; what Harmony runs herself -- every live row and every gate verdict is hers, never a builder's); 5 TESTS + GATE ROWS (exact strings and bars, pre-registered; each with its RED arm); 6 WHAT ONLY BORIS CAN CHECK (do -> expect -> what wrong looks like; on his real screens and by his ear); 7 QUESTIONS FOR BORIS; 8 RISKS (the strongest counterargument first; the cheapest refuting test for each choice); 9 WHAT IS NOT IN THIS LANE (incl. what is carried from, and what is dropped with, the stopped sync-dial branches, each with its commit).
${RULES}
TURN BUDGET (the architect role stops SILENTLY at 120 turns): write a SKELETON of the plan file with all headings by your turn 8; rewrite it with what you have every ~10 turns; be DONE by turn 90; if short, status PARTIAL with what is missing at the top.
REPORT_FILE: ${PLAN_FILE}
RETURN: plan_path, status, summary <= 1500 characters, forks (id, choice, runner_up), not_verified (what you could not establish by reading).`, { agentType: 'architect', model: 'opus', effort: 'high', schema: PS, phase: 'Plan', label: 'plan:' + KEY })
if (!plan) return { failed: 'plan' }
log('plan: ' + plan.status + ' -> ' + plan.plan_path)

phase('Attack')
const SEATS = A.seats || []
const papers = (await parallel(SEATS.map(s => () => agent(`BLIND COUNCIL SEAT "${s.key}" -- attack ONE plan from ONE temperament. You do not see the other seats.
${s.temper}
THE PLAN UNDER ATTACK: ${MAIN}/${PLAN_FILE} (read it IN FULL first).
${READS}
${INPUTS}
MANDATORY CITATION RE-CHECK: before you return, re-open every file:line, sheet row or record line you cite and confirm it says what you claim; set citations_rechecked accordingly and drop any attack whose evidence did not survive. An attack without evidence (a file:line at ${PIN}, a fact-sheet row, a quoted plan line, or a quoted line of Boris's verbatim record) is not an attack.
Do NOT write any file. RETURN (StructuredOutput): seat, attacks (id like ${s.key.slice(0, 2).toUpperCase()}-1..; target = the plan item / section; claim; evidence; severity MUST = the plan would ship a defect, contradict Boris's verbatim words, break a real-time or screen-safety rule, or carry a gate that cannot fail, SHOULD, NIT; proposed_change), strongest_point, citations_rechecked. At most 8 attacks, each field under 900 characters; fewer and sharper is better.`, { agentType: 'authored-council-seat', model: 'sonnet', effort: 'high', schema: AS, phase: 'Attack', label: 'attack:' + KEY + ':' + s.key })))).filter(Boolean)
const papersJson = JSON.stringify(papers)
const nAtt = papers.reduce((n, p) => n + (p.attacks || []).length, 0)
log('seats returned: ' + papers.length + ' of ' + SEATS.length + '; attacks: ' + nAtt + '; papers ' + papersJson.length + ' characters (passed WHOLE, no cut)')
if (papers.length < SEATS.length) log('MISSING SEATS: ' + SEATS.filter(s => !papers.some(p => String(p.seat || '').indexOf(s.key) >= 0)).map(s => s.key).join(', '))

phase('Ruling')
const ruling = await agent(`ARCHITECT RULING on a blind council's attacks, lane "${KEY}": ${A.title} (you run on opus at max effort because Fable is out of usage -- Boris, verbatim, 2026-10-02: "just so you know, we are out of fable usage so you will need to do all fable work with opus 5.5"). Harmony decides after you; your ruling is her working document.
THE PLAN: ${MAIN}/${PLAN_FILE} (read IN FULL).
THE SEAT PAPERS (${papers.length} of ${SEATS.length} seats returned; verbatim JSON, WHOLE -- ${papersJson.length} characters; if the text below does not end with a closed JSON array, STOP and return status PARTIAL saying so): ${papersJson}
${READS}
${INPUTS}
DO, IN THIS ORDER:
1. FIRST write the seat papers verbatim (pretty-printed, one section per seat) to ${PAPERS_FILE} (literal path, relative to ${MAIN}, bash heredoc).
2. For every attack: re-derive the evidence yourself in the code at ${PIN}, in the fact sheets or in Boris's record (never trust a seat's citation, never the plan's); verdict ACCEPT / PARTIAL / REJECT with the line that decides it. Reconcile seats that conflict. Where an outcome turns on a fact that only a run can establish, do NOT guess: name the measurement, who runs it (Harmony runs every live row), and give the ruling for EACH outcome. Where it turns on what Boris wants and his words do not settle it, it is a BORIS QUESTION with a default.
3. Write the ruling to REPORT_FILE: 0 VERDICT; 1 FACTS RE-DERIVED; 2 ATTACK RULINGS (table: one row per attack id); 3 AMENDMENTS (numbered; each OVERRIDES the plan body); 4 FINAL STAGES + ORDER (one builder context each; the files each owns; what each proves; what Harmony runs herself and when); 5 TESTS + GATE ROWS (pre-registered; exact strings and bars; each row's RED arm); 6 WHAT ONLY BORIS CAN CHECK; 7 BORIS QUESTIONS (numbers ${A.qFirst}..${A.qLast}; each with a default); 8 HARMONY'S DECISIONS (each with a default); 9 SIDE FINDINGS; 10 RISKS (the strongest counterargument first).
${RULES}
RULE FIRST, and state plainly at the top of section 0: ${(A.ruleFirst || []).join('; ')}.
TURN BUDGET (the role stops SILENTLY at 120 turns): papers file by turn 4; a SKELETON ruling with all headings by turn 10; rewrite every ~10 turns; DONE by turn 90; if short, status PARTIAL with what is missing at the top.
REPORT_FILE: ${RULING_FILE}
RETURN: ruling_path, papers_path, status, verdict (<= 1200 characters), amendments (count), attacks_ruled (count), stages (key + one-line scope), boris_questions, harmony_decisions, facts_harmony_must_measure, strongest_counterargument.`, { agentType: 'architect', model: 'opus', effort: 'max', schema: RS, phase: 'Ruling', label: 'ruling:' + KEY })
const cut = (s, n) => String(s || '').slice(0, n)
return { lane: KEY, plan: { path: plan.plan_path, status: plan.status, summary: cut(plan.summary, 1500), forks: (plan.forks || []).map(f => ({ id: f.id, choice: cut(f.choice, 260), runner_up: cut(f.runner_up, 200) })), not_verified: (plan.not_verified || []).map(x => cut(x, 240)) }, seats: papers.map(p => ({ seat: p.seat, n: (p.attacks || []).length, must: (p.attacks || []).filter(a => a.severity === 'MUST').length, strongest: cut(p.strongest_point, 300) })), attacks_sent: nAtt, papers_chars: papersJson.length, ruling: ruling ? { ruling_path: ruling.ruling_path, status: ruling.status, verdict: cut(ruling.verdict, 1200), amendments: ruling.amendments, attacks_ruled: ruling.attacks_ruled, stages: (ruling.stages || []).map(s => ({ key: s.key, scope: cut(s.scope, 300) })), boris_questions: (ruling.boris_questions || []).map(x => cut(x, 400)), harmony_decisions: (ruling.harmony_decisions || []).map(x => cut(x, 300)), facts_harmony_must_measure: (ruling.facts_harmony_must_measure || []).map(x => cut(x, 300)), strongest_counterargument: cut(ruling.strongest_counterargument, 500) } : { failed: true } }
